body:
// ==== What it does ====
// Finds source IP addresses that produce many failed interactive sign-ins and classifies them:
//   - PasswordSpray: many distinct users, few attempts per user
//   - BruteForce: few users, many attempts per user
//   - Mixed/other: everything above the volume threshold that fits neither pattern
// Error codes that only mean 'the user must complete an extra step' (MFA prompt, KMSI prompt) are excluded,
// because they are not real authentication failures and create most of the noise in this kind of query.

// ==== Required tables/columns ====
// SigninLogs: TimeGenerated, UserPrincipalName, IPAddress, ResultType (string), ResultDescription,
//   AppDisplayName, ClientAppUsed, LocationDetails (dynamic), IsInteractive.
// Workspace: Log Analytics workspace that receives the Entra ID 'SignInLogs' diagnostic category.

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback        = 24h;   // time window to analyse
let minFailures     = 20;    // minimum failed attempts per IP to be listed
let sprayMinUsers   = 8;     // distinct users from one IP that signals spraying
let sprayMaxPerUser = 5;     // average attempts per user must stay at or below this
// Result codes that are not credential failures but 'interrupts' (MFA required, KMSI, etc.)
let interruptCodes  = dynamic(["0", "50058", "50072", "50074", "50076", "50079", "50125", "50140"]);
// ---------------------------------------------------------------------------
SigninLogs
| where TimeGenerated > ago(lookback)
| where IsInteractive == true
| where ResultType !in (interruptCodes)
| extend Country = tostring(LocationDetails.countryOrRegion)
| summarize
    FailedAttempts = count(),
    DistinctUsers  = dcount(UserPrincipalName),
    DistinctApps   = dcount(AppDisplayName),
    Users          = make_set(UserPrincipalName, 25),
    Errors         = make_set(ResultType, 10),
    Countries      = make_set(Country, 5),
    FirstSeen      = min(TimeGenerated),
    LastSeen       = max(TimeGenerated)
    by IPAddress
| where FailedAttempts >= minFailures
| extend AttemptsPerUser = round(todouble(FailedAttempts) / DistinctUsers, 1)
| extend Pattern = case(
    DistinctUsers >= sprayMinUsers and AttemptsPerUser <= sprayMaxPerUser, "PasswordSpray",
    DistinctUsers <= 3 and AttemptsPerUser > sprayMaxPerUser,              "BruteForce",
    "Mixed")
| extend ActiveMinutes = datetime_diff("minute", LastSeen, FirstSeen)
| project IPAddress, Pattern, FailedAttempts, DistinctUsers, AttemptsPerUser, ActiveMinutes,
          Countries, Errors, FirstSeen, LastSeen, Users
| order by Pattern asc, FailedAttempts desc

// ---- Companion query: users that were hit hardest, with the final outcome ----
SigninLogs
| where TimeGenerated > ago(24h)
| where IsInteractive == true
| summarize
    Failures  = countif(ResultType !in ("0", "50058", "50072", "50074", "50076", "50079", "50125", "50140")),
    Successes = countif(ResultType == "0"),
    IPs       = dcount(IPAddress),
    LastEvent = max(TimeGenerated)
    by UserPrincipalName
| where Failures >= 10
// A success after many failures from many IPs is the pattern that deserves an immediate look.
| extend SuspiciousSuccess = Successes > 0 and IPs >= 3
| order by SuspiciousSuccess desc, Failures desc

// ==== How to adapt ====
// Lower minFailures for small tenants; raise it if one NAT gateway of a large office shows up.
// Add 'and ResultType in ("50126", "50053")' to focus on wrong password (50126) and locked account (50053).
// Join the result against a watchlist of corporate egress IPs (_GetWatchlist('CorpIPs')) and drop known ranges.
// To alert in Microsoft Sentinel, save the first query as an analytics rule, run every 1h over 1d,
//   and map IPAddress to the IP entity and Users to the Account entity.
// Repeat the logic on AADNonInteractiveUserSignInLogs for token-based spray against legacy clients.

// ==== Performance notes ====
// Filter on TimeGenerated first and keep the summarize by one compact key (IPAddress).
// make_set with a size limit (25, 10, 5) keeps result rows small and avoids memory pressure.
// dcount is approximate (HyperLogLog); that is fine for thresholds and much cheaper than exact counts.

// ==== Common mistakes ====
// Comparing ResultType to a number: in SigninLogs the column is a string, so use "0" and not 0.
// Forgetting interrupt codes: MFA prompts (50074, 50076) are not failures and inflate every count.
// Using UserPrincipalName for the key only: guest users show up with #EXT# names, normalise if needed.
// Treating a high count as proof of attack: CGNAT and misconfigured mail clients also produce bursts.

// ==== What it does ====
// Looks at successful sign-ins, orders them per user by time and uses prev() to compare consecutive events.
// The great-circle distance comes from geo_distance_2points(), the speed is distance divided by elapsed time.
// Rows are returned when the implied speed is above a threshold (default 900 km/h, roughly an airliner),
// the countries differ and the IP addresses differ. VPN exits and mobile carriers are the main false positives.

// ==== Required tables/columns ====
// SigninLogs: TimeGenerated, UserPrincipalName, IPAddress, ResultType, AppDisplayName,
//   LocationDetails (dynamic: city, countryOrRegion, geoCoordinates.latitude / longitude).

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback       = 3d;
let minDistanceKm  = 500;    // ignore short hops
let minSpeedKmh    = 900;    // faster than this is considered impossible
let ignoredApps    = dynamic(["__none__"]);   // e.g. dynamic(["Microsoft Intune Enrollment"])
// ---------------------------------------------------------------------------
SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType == "0"
| where AppDisplayName !in (ignoredApps)
| extend City    = tostring(LocationDetails.city),
         Country = tostring(LocationDetails.countryOrRegion),
         Lat     = todouble(LocationDetails.geoCoordinates.latitude),
         Lon     = todouble(LocationDetails.geoCoordinates.longitude)
| where isnotempty(Country) and isnotnull(Lat) and isnotnull(Lon)
| project TimeGenerated, UserPrincipalName, IPAddress, City, Country, Lat, Lon, AppDisplayName
// prev() needs a serialized (sorted) row set
| sort by UserPrincipalName asc, TimeGenerated asc
| serialize
| extend PrevUser    = prev(UserPrincipalName),
         PrevTime    = prev(TimeGenerated),
         PrevIP      = prev(IPAddress),
         PrevCity    = prev(City),
         PrevCountry = prev(Country),
         PrevLat     = prev(Lat),
         PrevLon     = prev(Lon),
         PrevApp     = prev(AppDisplayName)
| where UserPrincipalName == PrevUser
| where IPAddress != PrevIP and Country != PrevCountry
// geo_distance_2points(lon1, lat1, lon2, lat2) returns METERS - note longitude comes first
| extend DistanceKm = round(geo_distance_2points(PrevLon, PrevLat, Lon, Lat) / 1000.0, 0)
| extend Hours      = datetime_diff("second", TimeGenerated, PrevTime) / 3600.0
| where DistanceKm >= minDistanceKm
// guard against division by zero when two sign-ins carry the same timestamp
| extend SpeedKmh = round(DistanceKm / max_of(Hours, 0.01), 0)
| where SpeedKmh >= minSpeedKmh
| project UserPrincipalName,
          FromTime = PrevTime, FromCity = PrevCity, FromCountry = PrevCountry, FromIP = PrevIP, FromApp = PrevApp,
          ToTime = TimeGenerated, ToCity = City, ToCountry = Country, ToIP = IPAddress, ToApp = AppDisplayName,
          DistanceKm, Hours = round(Hours, 2), SpeedKmh
| order by SpeedKmh desc

// ==== How to adapt ====
// Tune minSpeedKmh (lower values such as 500 also catch fast ground travel but add noise, 1000 or more reduces noise) and minDistanceKm.
// Exclude trusted VPN or SASE egress ranges: where not(ipv4_is_in_range(IPAddress, '203.0.113.0/24')).
// Join to IdentityInfo or a watchlist to suppress shared service mailboxes or travelling executives.
// Add a second pass that requires different DeviceDetail.deviceId values to reduce false positives further.
// Entra ID Protection already raises an 'atypical travel' risk detection; use this as a transparent cross-check.

// ==== Performance notes ====
// Keep lookback short; sort and serialize run on the full projected row set in memory.
// Project only the needed columns before sort to reduce the data that has to be ordered.
// A 3-day window over a large tenant is fine; for 30 days, partition with 'partition by UserPrincipalName'.

// ==== Common mistakes ====
// Swapping longitude and latitude in geo_distance_2points: the function expects longitude first.
// Forgetting serialize: prev() raises an error or returns wrong rows on unsorted data.
// Comparing only events with different cities: city names change within one trip, compare countries.
// Ignoring that mobile network egress can geolocate to another country than the phone.

// ==== What it does ====
// Successful sign-ins whose AuthenticationRequirement is singleFactorAuthentication did not require MFA.
// The query groups them by user and by application, so you can see where a Conditional Access policy is missing,
// scoped too narrowly or excluded. It also reports how many of those sign-ins came from outside known countries.

// ==== Required tables/columns ====
// SigninLogs: TimeGenerated, UserPrincipalName, AppDisplayName, ResourceDisplayName, ResultType,
//   AuthenticationRequirement, ConditionalAccessStatus, ClientAppUsed, IPAddress, LocationDetails, IsInteractive.

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback = 30d;
// Resources that legitimately never prompt for MFA in your tenant (review and extend)
let excludedResources = dynamic(["Microsoft Intune Enrollment"]);
// Countries where you expect users; everything else is flagged
let homeCountries = dynamic(["DE", "AT", "CH", "US"]);
// ---------------------------------------------------------------------------
let SingleFactor =
    SigninLogs
    | where TimeGenerated > ago(lookback)
    | where ResultType == "0"
    | where IsInteractive == true
    | where AuthenticationRequirement == "singleFactorAuthentication"
    | where ResourceDisplayName !in (excludedResources)
    | extend Country = tostring(LocationDetails.countryOrRegion);
// 1) Users with the most single-factor sign-ins and the apps they used
// Part 1 and the let block above belong together; parts 2 and 3 stand alone
SingleFactor
| summarize
    SingleFactorSignIns = count(),
    Apps                = make_set(AppDisplayName, 10),
    ClientApps          = make_set(ClientAppUsed, 5),
    CAResults           = make_set(ConditionalAccessStatus, 5),
    OutsideHome         = countif(Country !in (homeCountries) and isnotempty(Country)),
    LastSeen            = max(TimeGenerated)
    by UserPrincipalName
| order by SingleFactorSignIns desc
| take 100

// 2) Applications ranked by the share of single-factor sign-ins
SigninLogs
| where TimeGenerated > ago(30d)
| where ResultType == "0" and IsInteractive == true
| summarize
    Total        = count(),
    SingleFactor = countif(AuthenticationRequirement == "singleFactorAuthentication"),
    Users        = dcount(UserPrincipalName)
    by AppDisplayName
| extend SingleFactorPct = round(100.0 * SingleFactor / Total, 1)
| where SingleFactor > 0
| order by SingleFactor desc

// 3) Legacy authentication, which cannot do MFA at all
SigninLogs
| where TimeGenerated > ago(30d)
| where ResultType == "0"
| where ClientAppUsed !in ("Browser", "Mobile Apps and Desktop clients")
| summarize Sessions = count(), Users = dcount(UserPrincipalName) by ClientAppUsed, AppDisplayName
| order by Sessions desc

// ==== How to adapt ====
// The let block is only shared by part 1; parts 2 and 3 are standalone queries.
// To test a planned policy, filter ConditionalAccessStatus == 'notApplied' and look at who would be hit.
// Use report-only results: expand ConditionalAccessPolicies and look for result 'reportOnlyFailure'.
// Add a join to IdentityInfo to exclude disabled accounts and break-glass accounts by name.

// ==== Performance notes ====
// Single-factor sign-ins can be very frequent, so summarize early and use take after ordering only.
// countif inside one summarize is faster than several separate filtered queries joined later.

// ==== Common mistakes ====
// Treating every single-factor row as a gap: a trusted-location or compliant-device policy can legitimately skip MFA.
// Using ConditionalAccessStatus alone: it only says whether a policy applied, not which control was granted.
// Looking only at interactive sign-ins and ignoring AADNonInteractiveUserSignInLogs for token refreshes.
// Putting two separate result sets in one saved analytics rule; a rule must return one table.

// ==== What it does ====
// Attackers who gain Application Administrator rights often add a client secret to an existing service principal and use it silently.
// Part 1 lists credential additions from AuditLogs with actor and target. Part 2 compares recent service principal
// sign-ins with a 30-day baseline of IP addresses and highlights those from IPs that never appeared before.

// ==== Required tables/columns ====
// AuditLogs: TimeGenerated, OperationName, Result, InitiatedBy (dynamic), TargetResources (dynamic), CorrelationId.
// AADServicePrincipalSignInLogs: TimeGenerated, ServicePrincipalId, ServicePrincipalName, AppId, IPAddress, ResultType, ResourceDisplayName.
// Both tables need the matching Entra ID diagnostic categories (AuditLogs, ServicePrincipalSignInLogs).

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Part 1: credentials added to apps or service principals --------------
AuditLogs
| where TimeGenerated > ago(14d)
| where OperationName has_any ("Add service principal credentials",
                               "Certificates and secrets management")
| where Result == "success"
| extend Actor      = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName)),
         ActorIP    = tostring(InitiatedBy.user.ipAddress),
         TargetName = tostring(TargetResources[0].displayName),
         TargetId   = tostring(TargetResources[0].id),
         TargetType = tostring(TargetResources[0].type)
| project TimeGenerated, OperationName, Actor, ActorIP, TargetName, TargetType, TargetId, CorrelationId
| order by TimeGenerated desc

// ---- Part 2: service principal sign-ins from IPs not seen in the baseline ---
let baselineStart = ago(30d);
let recentStart   = ago(2d);
let KnownIPs =
    AADServicePrincipalSignInLogs
    | where TimeGenerated >= baselineStart and TimeGenerated < recentStart
    | where ResultType == "0"
    | summarize by ServicePrincipalId, IPAddress;
AADServicePrincipalSignInLogs
| where TimeGenerated >= recentStart
| where ResultType == "0"
| summarize
    SignIns   = count(),
    Resources = make_set(ResourceDisplayName, 5),
    FirstSeen = min(TimeGenerated),
    LastSeen  = max(TimeGenerated)
    by ServicePrincipalId, ServicePrincipalName, AppId, IPAddress
// leftanti keeps only rows that have NO match in the baseline
| join kind=leftanti KnownIPs on ServicePrincipalId, IPAddress
| order by SignIns desc

// ---- Part 3 (optional): correlate - sign-ins of the same app within 24 hours after a credential change ----
let CredChanges =
    AuditLogs
    | where TimeGenerated > ago(7d)
    | where OperationName has_any ("Add service principal credentials", "Certificates and secrets management")
    | extend TargetName = tostring(TargetResources[0].displayName), ChangeTime = TimeGenerated
    | project ChangeTime, TargetName, Actor = tostring(InitiatedBy.user.userPrincipalName);
AADServicePrincipalSignInLogs
| where TimeGenerated > ago(7d) and ResultType == "0"
| join kind=inner CredChanges on $left.ServicePrincipalName == $right.TargetName
| where TimeGenerated between (ChangeTime .. ChangeTime + 24h)
| summarize SignIns = count(), IPs = make_set(IPAddress, 10) by ServicePrincipalName, Actor, ChangeTime

// ==== How to adapt ====
// Add 'Add owner to application' and 'Add app role assignment to service principal' to the has_any list of Part 1 to also see ownership and permission changes.
// Exclude automation: where Actor !in ('deployment-pipeline-app') or where ActorIP !startswith '10.'.
// For Microsoft Sentinel rules, wrap Part 1 alone and map Actor to Account and ActorIP to IP entities.
// Include managed identities with the AADManagedIdentitySignInLogs table if you use them.

// ==== Performance notes ====
// Narrow OperationName first; AuditLogs is large and has_any on a few phrases is cheap.
// join kind=leftanti with a small summarized right side is efficient; always summarize the baseline first.
// Keep baseline and recent windows disjoint (>= start and < boundary versus >= boundary) so a sign-in cannot count as both baseline and recent.

// ==== Common mistakes ====
// Matching OperationName with == : the portal uses an en dash in 'Update application - Certificates...'; use has_any.
// Assuming InitiatedBy.user always exists: app-initiated changes put the name in InitiatedBy.app.
// Using a baseline that is too short: rarely used automation looks new every time.
// Forgetting that ServicePrincipalSignInLogs must be enabled separately in the diagnostic setting.

// ==== What it does ====
// Runs against the 'resources' table of Azure Resource Graph (not Log Analytics).
// It builds a list of missing tag names per resource, skips types that cannot carry tags, and offers a summary
// per subscription so owners can be chased. Use it before assigning an Azure Policy 'require tag' effect with deny.

// ==== Required tables/columns ====
// Azure Resource Graph tables: resources (name, type, resourceGroup, subscriptionId, location, tags),
//   resourcecontainers (type 'microsoft.resources/subscriptions', name, subscriptionId).
// Run in the Azure portal (Resource Graph Explorer), Azure CLI 'az graph query' or Search-AzGraph.

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Detail list: every resource with at least one missing tag --------------
resources
// resource types that do not support tags or are noise
| where type !in~ ("microsoft.network/networkwatchers",
                   "microsoft.network/networkwatchers/flowlogs",
                   "microsoft.compute/virtualmachines/extensions",
                   "microsoft.alertsmanagement/smartdetectoralertrules")
| extend Owner       = tostring(tags['Owner']),
         CostCenter  = tostring(tags['CostCenter']),
         Environment = tostring(tags['Environment'])
| extend MissingOwner  = isempty(Owner),
         MissingCC     = isempty(CostCenter),
         MissingEnv    = isempty(Environment)
| where MissingOwner or MissingCC or MissingEnv
| extend MissingTags = strcat(
    iff(MissingOwner, "Owner ", ""),
    iff(MissingCC,    "CostCenter ", ""),
    iff(MissingEnv,   "Environment", ""))
| join kind=leftouter (
    resourcecontainers
    | where type == "microsoft.resources/subscriptions"
    | project subscriptionId, SubscriptionName = name
  ) on subscriptionId
| project SubscriptionName, resourceGroup, name, type, location, MissingTags, tags
| order by SubscriptionName asc, resourceGroup asc, type asc

// ---- Summary per subscription (run as a separate query) -----------------------
resources
| where type !in~ ("microsoft.network/networkwatchers", "microsoft.compute/virtualmachines/extensions")
| extend HasAll = isnotempty(tostring(tags['Owner']))
                  and isnotempty(tostring(tags['CostCenter']))
                  and isnotempty(tostring(tags['Environment']))
| summarize Total = count(), Compliant = countif(HasAll), NonCompliant = countif(not(HasAll)) by subscriptionId
| extend CompliancePct = round(100.0 * Compliant / Total, 1)
| join kind=leftouter (
    resourcecontainers
    | where type == "microsoft.resources/subscriptions"
    | project subscriptionId, SubscriptionName = name
  ) on subscriptionId
| project SubscriptionName, Total, Compliant, NonCompliant, CompliancePct
| order by NonCompliant desc

// ---- Resource groups (tags on the container itself) ----------------------------
resourcecontainers
| where type == "microsoft.resources/subscriptions/resourcegroups"
| where isempty(tostring(tags['Owner']))
| project subscriptionId, resourceGroup = name, location

// ==== How to adapt ====
// Replace the three tag names with your own standard; add more extend/iff pairs for further tags.
// Remove the type exclusions if you want every single resource, or extend them for types you cannot tag.
// Export with 'az graph query -q @query.kql --first 1000' and page using --skip for larger tenants.
// Use the same logic as Azure Policy 'Require a tag on resources' once the cleanup is done.

// ==== Performance notes ====
// Resource Graph is fast, but each call returns at most 1000 rows (the default and the maximum of --first / $top); page with --skip, which is ignored when the query itself uses take or limit.
// Only the join kinds innerunique, inner, leftouter and fullouter are supported, with at most three join or union operations per query.
// Prefer filtering on type early; avoid parse and regex on all rows.

// ==== Common mistakes ====
// Azure treats tag names as case-insensitive, but tags['Owner'] in the query is case-sensitive: a resource tagged 'owner' is reported as missing Owner.
// Reading tags with tags.Owner when the key contains spaces or hyphens: use the bracket form tags['Cost-Center'].
// Expecting resources inherit tags from the resource group: they do not unless a policy copies them.
// Running this text in Log Analytics: the resources table only exists in Resource Graph.

// ==== What it does ====
// Every Azure Monitor Agent or Log Analytics agent sends a heartbeat roughly once per minute.
// Part 1 shows computers whose last heartbeat is older than a threshold. Part 2 computes the availability
// (percentage of minutes with a heartbeat) so you can differentiate between dead machines and unstable connections.

// ==== Required tables/columns ====
// Heartbeat: TimeGenerated, Computer, Category, OSType, OSName, ComputerEnvironment,
//   ResourceGroup, SubscriptionId, ResourceId, Version, ComputerIP.

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Part 1: machines that went silent --------------------------------------
let silentAfter  = 15m;    // no heartbeat for this long counts as silent
let forgetAfter  = 14d;    // machines silent longer than this are probably decommissioned
Heartbeat
| where TimeGenerated > ago(forgetAfter)
| summarize
    LastHeartbeat = max(TimeGenerated),
    Category      = take_any(Category),
    OSType        = take_any(OSType),
    ResourceGroup = take_any(ResourceGroup)
    by Computer
| extend SilentFor = now() - LastHeartbeat
| where SilentFor > silentAfter
| extend Status = case(SilentFor < 1h,  "Just stopped",
                       SilentFor < 24h, "Down today",
                       "Down for days")
| project Computer, OSType, Category, ResourceGroup, LastHeartbeat, SilentFor, Status
| order by LastHeartbeat desc

// ---- Part 2: availability of the last 24 hours --------------------------------
let windowStart = ago(24h);
let totalMinutes = 24 * 60;
Heartbeat
| where TimeGenerated > windowStart
// one row per computer and minute first, then count the minutes: exact, unlike the approximate dcount()
| summarize by Computer, Minute = bin(TimeGenerated, 1m)
| summarize MinutesWithHeartbeat = count() by Computer
| extend AvailabilityPct = round(min_of(100.0, 100.0 * MinutesWithHeartbeat / totalMinutes), 2)
| where AvailabilityPct < 99
| order by AvailabilityPct asc

// ---- Part 3: chart of heartbeat count per 15 minutes for the worst machines ----
let Worst =
    Heartbeat
    | where TimeGenerated > ago(24h)
    | summarize Beats = count() by Computer
    | top 5 by Beats asc
    | project Computer;
Heartbeat
| where TimeGenerated > ago(24h)
| where Computer in (Worst)
| summarize Beats = count() by Computer, bin(TimeGenerated, 15m)
| render timechart

// ==== How to adapt ====
// Change silentAfter to 5m for critical servers; for scheduled-shutdown machines raise it or tag them out.
// Filter on ResourceGroup or ComputerEnvironment == 'Azure' to separate Azure VMs from Arc or on-premises servers.
// In Azure Monitor, create a log search alert on Part 1 with 'Number of results greater than 0'.
// Combine with the resources table in Resource Graph to detect VMs that have never reported at all.

// ==== Performance notes ====
// Heartbeat is small and cheap, but the distinct-minute count over many machines still scales with computers x minutes.
// Use take_any instead of max for columns that are constant per computer.
// Restrict the time range to what the alert needs; a 14-day scan is for reports, not for 5-minute alert rules.

// ==== Common mistakes ====
// Computing availability with count()/1440: duplicate heartbeats in one minute inflate the result; reduce to one row per bin(TimeGenerated, 1m) first.
// Treating every silent machine as an incident: deallocated dev VMs are normal.
// Reading a low availability for a machine onboarded today: it did not exist for the whole 24 hours.
// Forgetting that an alert on absence needs the data to exist in the lookback window at all.
// Mixing Computer name casing from different agents; use tolower(Computer) when joining to other tables.

// ==== What it does ====
// Reads performance counters collected by the agent into the Perf table and ranks machines by sustained load.
// Percentiles are far more informative than averages for capacity planning: a server that averages 30 percent CPU
// can still sit at 95 percent for an hour every night. The query handles Windows and Linux counter names.

// ==== Required tables/columns ====
// Perf: TimeGenerated, Computer, ObjectName, CounterName, InstanceName, CounterValue.
// Counters must be enabled in the Data Collection Rule (for example '\Processor Information(_Total)\% Processor Time'
//   and '\Memory\% Committed Bytes In Use' on Windows, 'Processor' and 'Memory' objects on Linux).

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback    = 7d;
let hotLevel    = 90.0;   // percent that counts as 'hot'
let minSamples  = 50;     // ignore machines with too little data
// ---------------------------------------------------------------------------
// Statements 2, 3 and 4 all use the 'Normalised' let block below: copy that let block in front of the statement you run,
//   because a let is not shared between separate runs.
// 1) Normalise CPU and memory counters from Windows (AMA and MMA) and Linux into one shape
let Normalised =
    Perf
    | where TimeGenerated > ago(lookback)
    | where (ObjectName in ("Processor", "Processor Information") and CounterName == "% Processor Time" and InstanceName == "_Total")
         or (ObjectName == "Memory" and CounterName in ("% Committed Bytes In Use", "% Used Memory"))
    | extend Metric = iff(CounterName == "% Processor Time", "CPU", "Memory")
    | project TimeGenerated, Computer, Metric, Value = CounterValue;
// 2) Per computer and metric statistics
Normalised
| summarize
    Samples = count(),
    Avg     = round(avg(Value), 1),
    P50     = round(percentile(Value, 50), 1),
    P95     = round(percentile(Value, 95), 1),
    P99     = round(percentile(Value, 99), 1),
    Max     = round(max(Value), 1),
    HotPct  = round(100.0 * countif(Value >= hotLevel) / count(), 1)
    by Computer, Metric
| where Samples >= minSamples
| order by P95 desc
| take 50

// 3) Wide view: one row per computer with CPU and memory side by side
Normalised
| summarize P95 = round(percentile(Value, 95), 1) by Computer, Metric
| summarize
    CpuP95 = maxif(P95, Metric == "CPU"),
    MemP95 = maxif(P95, Metric == "Memory")
    by Computer
| extend Verdict = case(
    CpuP95 >= 90 and MemP95 >= 90, "Undersized",
    CpuP95 >= 90,                  "CPU bound",
    MemP95 >= 90,                  "Memory bound",
    CpuP95 < 15 and MemP95 < 40,   "Oversized - candidate for resize",
    "OK")
| order by Verdict asc, CpuP95 desc

// 4) Chart: hourly average CPU of the five busiest machines
let Top5 =
    Normalised
    | where Metric == "CPU"
    | summarize AvgCpu = avg(Value) by Computer
    | top 5 by AvgCpu desc
    | project Computer;
Normalised
| where Metric == "CPU" and Computer in (Top5)
| summarize AvgCpu = avg(Value) by Computer, bin(TimeGenerated, 1h)
| render timechart

// ==== How to adapt ====
// Add '% Free Space' (LogicalDisk) or 'Avg. Disk sec/Transfer' counters in the same pattern for disk pressure.
// Lower hotLevel to 80 for latency-sensitive workloads; raise lookback to 30d for right-sizing exercises.
// Filter on Computer startswith 'sql' or a resource group via a join to Heartbeat to scope to one team.
// Windows '% Committed Bytes In Use' is the commit ratio (virtual memory), not physical RAM use; add 'Available MBytes' for physical pressure.
// Linux memory: '% Used Memory' counts caches, use '% Available Memory' with inverted logic if you prefer.

// ==== Performance notes ====
// percentile is more expensive than avg; keep the time range and computer set tight.
// Define the normalisation once in a let statement and reference it several times inside one query; for separate runs copy the let in front of each statement.
// If Perf volume is large, consider reducing the DCR sample frequency from 10 s to 60 s.

// ==== Common mistakes ====
// Averaging averages: CounterValue is already a sample; always aggregate raw samples.
// Mixing Processor and Processor Information instances: filter InstanceName == '_Total' or you count every core.
// Judging 'oversized' from one week that excludes month-end peaks.
// Reading the Verdict column without checking sample counts: a machine with a few samples gives unstable percentiles.

// ==== What it does ====
// After a mailbox takeover attackers create inbox rules that forward mail to an external address, delete replies,
// or move messages containing words like 'invoice' or 'security' into obscure folders. This query reads the
// Exchange audit events (New-InboxRule and Set-InboxRule from the Exchange admin audit log), turns the Parameters array into columns
// and scores each rule so the worst ones sort to the top.

// ==== Required tables/columns ====
// OfficeActivity (Microsoft 365 connector in Sentinel): TimeGenerated, OfficeWorkload, Operation, UserId,
//   ClientIP, Parameters (JSON array of Name/Value pairs), OfficeObjectId, ResultStatus.
// Mailbox auditing must be on (default for Microsoft 365, verify with Get-OrganizationConfig).

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback = 14d;
let ruleOps  = dynamic(["New-InboxRule", "Set-InboxRule"]);
let hideFolders = dynamic(["RSS Feeds", "RSS Subscriptions", "Conversation History", "Archive", "Junk Email", "Deleted Items"]);
let keywords = dynamic(["invoice", "payment", "wire", "bank", "password", "security", "phish", "hacked", "iban", "urgent"]);
let corpDomain = "contoso.com";   // your own mail domain, used to detect external targets
// ---------------------------------------------------------------------------
OfficeActivity
| where TimeGenerated > ago(lookback)
| where OfficeWorkload == "Exchange" and Operation in~ (ruleOps)
| where ResultStatus in~ ("True", "Succeeded", "Success", "PartiallySucceeded")
// Parameters is an array of {Name, Value}; turn it into one property bag per row
| extend Params = todynamic(Parameters)
| mv-apply p = Params on (
    summarize Bag = make_bag(bag_pack(tostring(p.Name), tostring(p.Value))))
| extend RuleName    = coalesce(tostring(Bag.Name), OfficeObjectId),
         ForwardTo   = coalesce(tostring(Bag.ForwardTo), tostring(Bag.RedirectTo), tostring(Bag.ForwardAsAttachmentTo)),
         DeleteMsg   = tostring(Bag.DeleteMessage) =~ "True",
         MoveTo      = tostring(Bag.MoveToFolder),
         SubjectKeys = strcat(tostring(Bag.SubjectContainsWords), " ", tostring(Bag.SubjectOrBodyContainsWords), " ", tostring(Bag.BodyContainsWords)),
         MarkRead    = tostring(Bag.MarkAsRead) =~ "True"
| extend ExternalForward = isnotempty(ForwardTo) and not(ForwardTo has corpDomain),
         HidesMail       = DeleteMsg or MoveTo has_any (hideFolders),
         KeywordHit      = SubjectKeys has_any (keywords)
// simple additive risk score
| extend Score = iff(ExternalForward, 5, 0) + iff(isnotempty(ForwardTo), 2, 0)
                + iff(HidesMail, 2, 0) + iff(KeywordHit, 2, 0) + iff(MarkRead, 1, 0)
| where Score >= 3
| project TimeGenerated, UserId, Operation, RuleName, ForwardTo, DeleteMsg, MoveTo, MarkRead,
          SubjectKeys, ClientIP, Score, ExternalForward, HidesMail, KeywordHit
| order by Score desc, TimeGenerated desc

// ==== How to adapt ====
// Replace contoso.com with your accepted domains; add a list of partner domains that may receive forwards.
// 'has corpDomain' is a simple check: a recipient list that mixes internal and external addresses counts as internal, so tighten it with a regex if needed.
// Correlate ClientIP with SigninLogs for the same user in the hour before the rule was created.
// Add the 'Set-Mailbox' operation with ForwardingSmtpAddress or ForwardingAddress parameters for mailbox-level forwarding.
// Pair with the Defender XDR table CloudAppEvents (ActionType 'New-InboxRule') if you use Defender for Cloud Apps.

// ==== Performance notes ====
// Filter OfficeWorkload and Operation before parsing JSON; mv-apply on all Exchange events would be very costly.
// make_bag over bag_pack is cheap per row, but keep the lookback moderate (14 to 30 days).
// Score thresholds are applied after parsing, so keep the pre-filter as narrow as possible.

// ==== Common mistakes ====
// Expecting Parameters to be a ready-made object: it is an array of name/value pairs and needs mv-apply.
// Comparing booleans with == true: values arrive as the string 'True', hence the =~ comparison.
// Rules created in Outlook clients are logged as UpdateInboxRules (mailbox audit) with the rule details in OperationProperties, not Parameters; this query does not parse them, so cover them with a second query.
// Alerting on every forward: legitimate out-of-office or shared-mailbox rules exist; keep the score threshold.

// ==== What it does ====
// Encoded PowerShell (-EncodedCommand and its abbreviations) is used by admins and by attackers alike.
// This hunt extracts the Base64 string from the command line, decodes it, removes the UTF-16 null bytes and
// searches the decoded script for suspicious building blocks such as IEX, DownloadString and AMSI tampering.
// Results list one row per execution, ordered by risk; the overview query at the end summarises per parent process to spot outliers.

// ==== Required tables/columns ====
// DeviceProcessEvents (Defender XDR / Microsoft Defender for Endpoint): Timestamp, DeviceName, DeviceId, AccountName,
//   AccountDomain, FileName, ProcessCommandLine, InitiatingProcessFileName, InitiatingProcessCommandLine,
//   InitiatingProcessParentFileName, ProcessIntegrityLevel, SHA256, ReportId.
// Run in security.microsoft.com under Hunting > Advanced hunting, or in Sentinel when the Defender XDR connector is on (there, replace Timestamp with TimeGenerated).

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback = 7d;
// Parents that commonly run encoded commands for good reasons (extend after review)
let knownParents = dynamic(["ccmexec.exe", "healthservice.exe", "monitoringhost.exe"]);
// ---------------------------------------------------------------------------
DeviceProcessEvents
| where Timestamp > ago(lookback)
| where FileName in~ ("powershell.exe", "pwsh.exe", "powershell_ise.exe")
// -e, -ec, -en, -enc ... -encodedcommand (all valid abbreviations) followed by a long Base64 string.
// The pattern deliberately does not match -ExecutionPolicy, which also starts with -e.
| where ProcessCommandLine matches regex @"(?i)\s-e(c|n[a-z]*)?\s+[A-Za-z0-9+/=]{20,}"
| extend EncodedPart = extract(@"(?i)\s-e(?:c|n[a-z]*)?\s+([A-Za-z0-9+/=]{20,})", 1, ProcessCommandLine)
// PowerShell encodes in UTF-16LE: strip non-printable characters after decoding
| extend Decoded = replace_regex(base64_decode_tostring(EncodedPart), @"[^\x20-\x7E]", "")
| where isnotempty(Decoded)
// count suspicious building blocks; the single capture group is required by extract_all
| extend TokenHits = array_length(extract_all(
        @"(?i)(?:^|[\s;|(.:])(iex|invoke-expression|downloadstring|downloadfile|net\.webclient|frombase64string|-nop|-noprofile|-w hidden|-windowstyle hidden|amsiutils|invoke-mimikatz|reflection\.assembly|invoke-webrequest|start-bitstransfer|add-mppreference)\b",
        Decoded))
| extend HasUrl = Decoded matches regex @"(?i)https?://"
| where InitiatingProcessFileName !in~ (knownParents)
| extend Risk = case(TokenHits >= 2 or (TokenHits >= 1 and HasUrl), "High",
                     TokenHits == 1 or HasUrl,                     "Medium",
                     "Low")
| extend RiskRank = case(Risk == "High", 1, Risk == "Medium", 2, 3)
| project Timestamp, DeviceName, AccountDomain, AccountName, Risk, RiskRank, TokenHits, HasUrl,
          Parent = InitiatingProcessFileName, GrandParent = InitiatingProcessParentFileName,
          ParentCmd = InitiatingProcessCommandLine,
          Decoded = substring(Decoded, 0, 400), SHA256, ReportId
// sort by the rank: sorting the text 'Risk' would give High, Low, Medium
| order by RiskRank asc, Timestamp desc
| project-away RiskRank

// ---- Overview: who launches encoded PowerShell most often? --------------------
DeviceProcessEvents
| where Timestamp > ago(30d)
| where FileName =~ "powershell.exe" and ProcessCommandLine matches regex @"(?i)\s-e(c|n[a-z]*)?\s+[A-Za-z0-9+/=]{20,}"
| summarize Runs = count(), Devices = dcount(DeviceId), Accounts = dcount(AccountName)
    by InitiatingProcessFileName
| order by Runs desc

// ==== How to adapt ====
// Add every legitimate management tool to knownParents after you verified it; the overview query shows candidates.
// Raise the Base64 length to 40 to skip short test strings, or lower it to 12 to catch tiny stagers.
// Turn it into a custom detection rule: add ReportId, DeviceId and Timestamp to the output and schedule hourly.
// Include 'cmd.exe /c powershell' chains by also checking InitiatingProcessCommandLine.

// ==== Performance notes ====
// Filter by FileName and Timestamp first; the regex and decoding only run on the reduced row set.
// Advanced Hunting limits results to 10,000 rows and 30 days of data; keep lookback within that.
// Avoid decoding inside a where over all rows; extend after the cheap filters, as done here.

// ==== Common mistakes ====
// Decoding without stripping NUL bytes: base64_decode_tostring on UTF-16 text gives 'p o w e r s h e l l' with gaps.
// Matching only '-EncodedCommand': attackers use -e, -ec or -enc. The regex covers abbreviations.
// Using Timestamp in Log Analytics tables: the Sentinel copy of this data uses TimeGenerated.
// Treating Low risk as safe: short encoded stagers often have no readable keywords.

// ==== What it does ====
// Aggregates failed logons per source IP, target account and machine, then joins to successful logons that follow
// within a configurable window. The result lists accounts that got in after repeated failures and shows
// how long the guessing lasted and how many failures preceded the success.

// ==== Required tables/columns ====
// SecurityEvent: TimeGenerated, EventID, Computer, TargetUserName, TargetDomainName, IpAddress, LogonType,
//   Status, SubStatus, WorkstationName, LogonProcessName, AuthenticationPackageName.
// Collected by the Windows Security Events connector (AMA); the 'Common' or 'All events' set contains 4624 and 4625.

// ==== Query ====
// The statements below are independent parts: run them one at a time unless stated otherwise.
// ---- Parameters -----------------------------------------------------------
let lookback       = 1d;
let failThreshold  = 10;     // failed logons before we care
let successWindow  = 30m;    // success must follow the last failure within this time
let remoteLogons   = dynamic([3, 10]);      // 3 = network, 10 = RemoteInteractive (RDP)
let ignoredIPs     = dynamic(["-", "::1", "127.0.0.1", ""]);
// ---------------------------------------------------------------------------
let Failures =
    SecurityEvent
    | where TimeGenerated > ago(lookback)
    | where EventID == 4625
    | where LogonType in (remoteLogons)
    | where IpAddress !in (ignoredIPs)
    | where TargetUserName !endswith "$"          // skip machine accounts
    | summarize
        FailCount = count(),
        FirstFail = min(TimeGenerated),
        LastFail  = max(TimeGenerated),
        SubStatuses = make_set(SubStatus, 5)
        by Computer, IpAddress, TargetUserName, TargetDomainName
    | where FailCount >= failThreshold;
let Successes =
    SecurityEvent
    | where TimeGenerated > ago(lookback)
    | where EventID == 4624
    | where LogonType in (remoteLogons)
    | where IpAddress !in (ignoredIPs)
    | project SuccessTime = TimeGenerated, Computer, IpAddress, TargetUserName, TargetDomainName, LogonType, LogonProcessName;
Failures
| join kind=inner Successes on Computer, IpAddress, TargetUserName, TargetDomainName
// the success must come after the last failure and within the window
| where SuccessTime >= LastFail and SuccessTime <= LastFail + successWindow
| extend GuessingMinutes = datetime_diff("minute", LastFail, FirstFail)
| summarize
    FirstSuccess = min(SuccessTime),
    SuccessLogons = count(),
    SubStatuses   = take_any(SubStatuses)
    by Computer, IpAddress, TargetUserName, TargetDomainName, FailCount, FirstFail, LastFail,
       GuessingMinutes, LogonType
| project Computer, IpAddress, Account = strcat(TargetDomainName, "\\", TargetUserName),
          LogonType, FailCount, GuessingMinutes, FirstFail, LastFail, FirstSuccess, SuccessLogons, SubStatuses
| order by FailCount desc

// ---- Reference: common SubStatus values for 4625 (SecurityEvent stores them as lowercase hex strings) ----
//   0xc000006a  wrong password for a valid user
//   0xc0000064  user name does not exist
//   0xc0000234  account locked out
//   0xc0000072  account disabled
//   0xc000006d  generic logon failure (bad user name or authentication info)

// ==== How to adapt ====
// Lower failThreshold to 5 for administrator accounts; add 'and TargetUserName =~ "administrator"' for a focused hunt.
// Add LogonType 2 and 7 if you want console unlock and workstation guessing as well.
// Enrich IpAddress with geo_info_from_ip_address(IpAddress) and add a threat intelligence join.
// Run on a schedule of 15m over a 1h lookback for a Sentinel analytics rule and entity-map Account and IP.

// ==== Performance notes ====
// Join keys Computer, IpAddress, TargetUserName keep the join small; summarise failures before joining.
// Put the smaller table on the left side of the join; here the aggregated Failures table is smaller than the Successes set.
// SecurityEvent can be huge: always filter on EventID and TimeGenerated first.

// ==== Common mistakes ====
// Joining without Computer: a success on server B after guessing against server A is a different story.
// Including machine accounts or '-' source addresses, which flood the result with local noise.
// Using only EventID 4625 for lockout detection: lockouts are 4740.
// Forgetting that RDP behind Network Level Authentication logs LogonType 3, not only 10.
